SELECT 
  quote_depth_snapshot || '{"spread_percentage": 0.09}'::jsonb AS updated_snapshot
FROM marketdata LIMIT 1;

SELECT 
  quote_depth_snapshot || jsonb_build_object('Spread Percentage', ROUND(((quote_depth_snapshot->'quotes'->>'askquote')::numeric - (quote_depth_snapshot->'quotes'->>'bidquote')::numeric) / (quote_depth_snapshot->'quotes'->>'midquote')::numeric * 100, 2)) AS updated_snapshot
FROM marketdata LIMIT 3;

UPDATE marketdata 
SET quote_depth_snapshot = quote_depth_snapshot || jsonb_build_object('Spread Percentage', ROUND(((quote_depth_snapshot->'quotes'->>'askquote')::numeric - (quote_depth_snapshot->'quotes'->>'bidquote')::numeric) / (quote_depth_snapshot->'quotes'->>'midquote')::numeric * 100, 2));

SELECT COUNT(*) FROM marketdata;

SELECT 
  quote_depth_snapshot || jsonb_build_object('Spread Percentage', ROUND(((quote_depth_snapshot->'quotes'->>'askquote')::numeric - (quote_depth_snapshot->'quotes'->>'bidquote')::numeric) / (quote_depth_snapshot->'quotes'->>'midquote')::numeric * 100, 2)) AS updated_quote_depth_snapshot
FROM marketdata LIMIT 5;
